with d as (select value r from jsonb_array_elements($q$[{"slug":"lahmacun","title":"Lahmacun","cuisine":"turkish","meal_types":["lunch","dinner"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":120,"recipe":{"id":"lahmacun","title":"Lahmacun","summary":"Thin, crisp Turkish flatbreads spread with spiced lamb, then rolled up with parsley, onion and lemon.","cuisine":"turkish","diets":["no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"medium","prepMinutes":90,"cookMinutes":30,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Dough","items":[{"item":"plain flour","raw":"400g plain flour","quantity":400,"unit":"g","ingredientId":"plain-flour"},{"item":"instant dried yeast","raw":"7g instant dried yeast","quantity":7,"unit":"g","ingredientId":"yeast"},{"item":"white sugar","raw":"1 tsp white sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"warm water","raw":"250ml warm water","quantity":250,"unit":"ml","ingredientId":"water"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"}]},{"title":"Topping","items":[{"item":"lamb mince","raw":"300g lamb mince","quantity":300,"unit":"g","ingredientId":"lamb-mince"},{"item":"small brown onion","raw":"1 small brown onion, roughly chopped","quantity":1,"ingredientId":"brown-onion","prep":"roughly chopped"},{"item":"red capsicum","raw":"1/2 red capsicum, roughly chopped","quantity":0.5,"ingredientId":"capsicum","prep":"roughly chopped"},{"item":"tomato","raw":"1 tomato, roughly chopped","quantity":1,"ingredientId":"tomato","prep":"roughly chopped"},{"item":"garlic","raw":"2 garlic cloves","quantity":2,"unit":"clove","ingredientId":"garlic"},{"item":"tomato paste","raw":"2 tbsp tomato paste","quantity":2,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"flat-leaf parsley leaves","raw":"1/2 cup flat-leaf parsley leaves","quantity":0.5,"unit":"cup","ingredientId":"parsley"},{"item":"Aleppo pepper","raw":"2 tsp Aleppo pepper","quantity":2,"unit":"tsp","ingredientId":"aleppo-pepper"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"sweet paprika","raw":"1 tsp sweet paprika","quantity":1,"unit":"tsp","ingredientId":"paprika"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"red onion","raw":"1 red onion, thinly sliced","quantity":1,"ingredientId":"red-onion","prep":"thinly sliced"},{"item":"sumac","raw":"1 tsp sumac","quantity":1,"unit":"tsp","ingredientId":"sumac"},{"item":"flat-leaf parsley","raw":"1 bunch flat-leaf parsley, leaves picked","quantity":1,"unit":"bunch","ingredientId":"parsley","prep":"leaves picked"},{"item":"lemons","raw":"2 lemons, cut into wedges","quantity":2,"ingredientId":"lemon","prep":"cut into wedges"}]}],"steps":[{"text":"Mix the flour, yeast, sugar and salt in a bowl. Add the water and oil and bring together, then knead for 8 minutes until smooth. Cover and leave in a warm place for 1 hour, until doubled."},{"text":"For the topping, blitz the onion, capsicum, tomato, garlic and parsley in a food processor until finely chopped but not puréed. Add the lamb, tomato paste, spices and salt and pulse to a smooth paste. Keep it in the fridge until needed."},{"text":"Heat the oven to 250°C (230°C fan-forced) with two oven trays inside. Divide the dough into 8 balls and roll each out on a floured bench as thinly as you can, to about 25 x 15cm."},{"text":"Lay two or three bases on a sheet of baking paper and spread each with a thin, even layer of the lamb, right to the edges."},{"text":"Slide the paper onto a hot tray and bake for 7 to 9 minutes, until the edges are crisp and the lamb is browned and cooked through. Repeat with the rest."},{"text":"Toss the red onion with the sumac. Serve the lahmacun hot, scattered with onion and parsley and squeezed with lemon, then rolled up to eat."}],"notes":["The lamb layer must be thin so it cooks through in the short bake. If yours is thicker, give it a couple of minutes more.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"imam-bayildi","title":"Imam Bayildi","cuisine":"turkish","meal_types":["dinner","lunch"],"diets":["vegetarian","vegan","no-gluten","no-dairy"],"difficulty":"medium","total_minutes":95,"recipe":{"id":"imam-bayildi","title":"Imam Bayildi","summary":"Whole eggplants braised in olive oil and stuffed with sweet, slow-cooked onion, garlic and tomato.","cuisine":"turkish","diets":["vegetarian","vegan","no-gluten","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"medium","prepMinutes":25,"cookMinutes":70,"servings":4,"onePot":false,"seasons":["summer","autumn"],"ingredientGroups":[{"items":[{"item":"medium eggplants","raw":"4 medium eggplants","quantity":4,"ingredientId":"eggplant"},{"item":"salt","raw":"2 tsp salt","quantity":2,"unit":"tsp","ingredientId":"salt"},{"item":"olive oil","raw":"125ml olive oil","quantity":125,"unit":"ml","ingredientId":"olive-oil"},{"item":"brown onions","raw":"3 brown onions, thinly sliced","quantity":3,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"garlic","raw":"6 garlic cloves, sliced","quantity":6,"unit":"clove","ingredientId":"garlic","prep":"sliced"},{"item":"ripe tomatoes","raw":"4 ripe tomatoes, chopped","quantity":4,"ingredientId":"tomato","prep":"chopped"},{"item":"tomato paste","raw":"1 tbsp tomato paste","quantity":1,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"white sugar","raw":"1 tsp white sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"flat-leaf parsley","raw":"1/2 cup flat-leaf parsley, chopped","quantity":0.5,"unit":"cup","ingredientId":"parsley","prep":"chopped"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"}]},{"title":"To serve","items":[{"item":"Crusty bread","raw":"Crusty bread, to serve (optional)","ingredientId":"crusty-bread","prep":"to serve","optional":true}]}],"steps":[{"text":"Peel the eggplants lengthways in stripes, leaving the stalks on. Make a deep slit down the length of each, without cutting through the ends or the base. Sprinkle with half the salt, inside and out, and leave for 15 minutes. Rinse and pat dry."},{"text":"Heat 4 tbsp of the oil in a large frying pan over medium heat and fry the eggplants for 10 minutes, turning, until golden and starting to soften. Lay them slit-side up in a baking dish."},{"text":"In the same pan, add 2 tbsp more oil and cook the onions over medium-low heat for 15 minutes until very soft and sweet. Add the garlic for 2 minutes, then the tomatoes, tomato paste, sugar, the rest of the salt and the pepper. Cook for 5 minutes, then stir in most of the parsley."},{"text":"Heat the oven to 180°C (160°C fan-forced). Open the slits and pack the eggplants with the filling, piling any extra around them. Pour over the water and the remaining oil."},{"text":"Cover with foil and bake for 30 minutes, then uncover and bake for 10 to 15 minutes more until the eggplants are completely soft."},{"text":"Cool to warm or room temperature, which is how it's traditionally eaten. Scatter with the remaining parsley and serve with bread."}],"notes":["The name means 'the imam fainted', said to be at how good it was (or at how much olive oil it used)."],"source":"user","provenance":"ai-draft"}},{"slug":"gozleme","title":"Spinach and Feta Gözleme","cuisine":"turkish","meal_types":["lunch","snack"],"diets":["vegetarian"],"difficulty":"medium","total_minutes":75,"recipe":{"id":"gozleme","title":"Spinach and Feta Gözleme","summary":"Thin Turkish griddle breads folded around spinach, feta and onion, cooked crisp in a dry pan with butter.","cuisine":"turkish","diets":["vegetarian"],"mealTypes":["lunch","snack"],"difficulty":"medium","prepMinutes":50,"cookMinutes":25,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Dough","items":[{"item":"plain flour","raw":"400g plain flour","quantity":400,"unit":"g","ingredientId":"plain-flour"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"warm water","raw":"250ml warm water","quantity":250,"unit":"ml","ingredientId":"water"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"}]},{"title":"Filling","items":[{"item":"olive oil","raw":"1 tbsp olive oil","quantity":1,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onion","raw":"1 brown onion, finely chopped","quantity":1,"ingredientId":"brown-onion","prep":"finely chopped"},{"item":"baby spinach","raw":"250g baby spinach, chopped","quantity":250,"unit":"g","ingredientId":"baby-spinach","prep":"chopped"},{"item":"feta","raw":"200g feta, crumbled","quantity":200,"unit":"g","ingredientId":"feta","prep":"crumbled"},{"item":"Aleppo pepper","raw":"1/2 tsp Aleppo pepper","quantity":0.5,"unit":"tsp","ingredientId":"aleppo-pepper"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"To cook and serve","items":[{"item":"butter","raw":"40g butter, melted","quantity":40,"unit":"g","ingredientId":"butter","prep":"melted"},{"item":"lemon","raw":"1 lemon, cut into wedges","quantity":1,"ingredientId":"lemon","prep":"cut into wedges"}]}],"steps":[{"text":"Mix the flour and salt, add the water and oil and bring together into a soft dough. Knead for 5 minutes until smooth, then divide into 4 balls, cover and rest for 30 minutes."},{"text":"Meanwhile, warm the oil in a large frying pan over medium heat and cook the onion for 5 minutes. Add the spinach and stir until wilted, then tip into a sieve and press out the liquid. Cool, then mix with the feta, Aleppo pepper and black pepper."},{"text":"On a floured bench, roll each ball into a very thin rectangle about 30 x 40cm. Spread a quarter of the filling over one half, fold the other half over and press the edges to seal."},{"text":"Heat a large dry frying pan or flat griddle over medium heat. Cook one gözleme at a time for 3 minutes a side, brushing the top with melted butter before turning, until crisp and golden in spots."},{"text":"Cut into pieces and serve hot with lemon wedges."}],"notes":["Swap half the spinach for cooked lamb mince, or add some grated mozzarella for a stretchier filling."],"source":"user","provenance":"ai-draft"}},{"slug":"manakish","title":"Za'atar Manakish","cuisine":"middle-eastern","meal_types":["breakfast","snack"],"diets":["vegetarian","vegan","no-dairy"],"difficulty":"easy","total_minutes":110,"recipe":{"id":"manakish","title":"Za'atar Manakish","summary":"Lebanese breakfast flatbreads spread with za'atar and olive oil, baked hot and eaten with tomato, cucumber and mint.","cuisine":"middle-eastern","diets":["vegetarian","vegan","no-dairy"],"mealTypes":["breakfast","snack"],"difficulty":"easy","prepMinutes":90,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Dough","items":[{"item":"plain flour","raw":"400g plain flour","quantity":400,"unit":"g","ingredientId":"plain-flour"},{"item":"instant dried yeast","raw":"7g instant dried yeast","quantity":7,"unit":"g","ingredientId":"yeast"},{"item":"white sugar","raw":"1 tsp white sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"warm water","raw":"250ml warm water","quantity":250,"unit":"ml","ingredientId":"water"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"}]},{"title":"Topping","items":[{"item":"za'atar","raw":"5 tbsp za'atar","quantity":5,"unit":"tbsp","ingredientId":"zaatar"},{"item":"extra virgin olive oil","raw":"100ml extra virgin olive oil","quantity":100,"unit":"ml","ingredientId":"olive-oil"}]},{"title":"To serve","items":[{"item":"tomatoes","raw":"2 tomatoes, sliced","quantity":2,"ingredientId":"tomato","prep":"sliced"},{"item":"Lebanese cucumbers","raw":"2 Lebanese cucumbers, sliced","quantity":2,"ingredientId":"cucumber","prep":"sliced"},{"item":"mint leaves","raw":"Handful of mint leaves","quantity":1,"unit":"handful","ingredientId":"mint"},{"item":"labneh","raw":"200g labneh (optional)","quantity":200,"unit":"g","ingredientId":"labneh","optional":true}]}],"steps":[{"text":"Mix the flour, yeast, sugar and salt, add the water and oil and knead for 8 minutes until smooth and elastic. Cover and leave in a warm place for 1 hour, until doubled."},{"text":"Heat the oven to 250°C (230°C fan-forced) with two oven trays inside. Mix the za'atar and olive oil to a loose paste."},{"text":"Divide the dough into 6 balls and roll each into a 20cm round. Lay them on sheets of baking paper and press dimples all over with your fingertips."},{"text":"Spread each with the za'atar oil, leaving a thin border. Slide onto the hot trays and bake for 7 to 9 minutes until the edges are golden and the base is crisp."},{"text":"Serve warm, folded around tomato, cucumber, mint and labneh."}],"notes":["With the labneh left out, they're vegan."],"source":"user","provenance":"ai-draft"}},{"slug":"baked-kibbeh","title":"Baked Kibbeh","cuisine":"middle-eastern","meal_types":["dinner"],"diets":[],"difficulty":"medium","total_minutes":90,"recipe":{"id":"baked-kibbeh","title":"Baked Kibbeh","summary":"A tray of spiced lamb and bulgur, layered around a pine nut and onion filling and baked until crisp-edged.","cuisine":"middle-eastern","diets":[],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":40,"cookMinutes":50,"servings":6,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Shell","items":[{"item":"fine bulgur","raw":"250g fine bulgur","quantity":250,"unit":"g","ingredientId":"bulgur"},{"item":"lamb mince","raw":"500g lamb mince","quantity":500,"unit":"g","ingredientId":"lamb-mince"},{"item":"brown onion","raw":"1 brown onion, roughly chopped","quantity":1,"ingredientId":"brown-onion","prep":"roughly chopped"},{"item":"ground allspice","raw":"1 1/2 tsp ground allspice","quantity":1.5,"unit":"tsp","ingredientId":"allspice"},{"item":"ground cinnamon","raw":"1/2 tsp ground cinnamon","quantity":0.5,"unit":"tsp","ingredientId":"ground-cinnamon"},{"item":"salt","raw":"1 1/2 tsp salt","quantity":1.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"iced water","raw":"4 tbsp iced water","quantity":4,"unit":"tbsp","ingredientId":"water"}]},{"title":"Filling","items":[{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onions","raw":"2 brown onions, finely chopped","quantity":2,"ingredientId":"brown-onion","prep":"finely chopped"},{"item":"lamb mince","raw":"300g lamb mince","quantity":300,"unit":"g","ingredientId":"lamb-mince"},{"item":"pine nuts","raw":"60g pine nuts","quantity":60,"unit":"g","ingredientId":"pine-nuts"},{"item":"ground allspice","raw":"1 tsp ground allspice","quantity":1,"unit":"tsp","ingredientId":"allspice"},{"item":"ground cinnamon","raw":"1/2 tsp ground cinnamon","quantity":0.5,"unit":"tsp","ingredientId":"ground-cinnamon"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"To finish and serve","items":[{"item":"olive oil","raw":"4 tbsp olive oil","quantity":4,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"Greek yoghurt","raw":"300g Greek yoghurt","quantity":300,"unit":"g","ingredientId":"greek-yoghurt"},{"item":"Lebanese cucumbers","raw":"2 Lebanese cucumbers, diced","quantity":2,"ingredientId":"cucumber","prep":"diced"}]}],"steps":[{"text":"Rinse the bulgur in a sieve, then soak in cold water for 15 minutes. Drain and squeeze out as much water as you can."},{"text":"For the filling, heat the oil in a frying pan over medium heat and cook the onions for 8 minutes until soft. Add the mince and cook for 8 minutes, breaking it up, until browned. Stir in the pine nuts, spices and salt and cook for 2 minutes. Cool."},{"text":"For the shell, blitz the onion in a food processor until fine. Add the bulgur, lamb, spices, salt and pepper and process, adding the iced water a spoonful at a time, until it forms a smooth, sticky paste (do it in two batches if your processor is small)."},{"text":"Heat the oven to 190°C (170°C fan-forced) and oil a 23 x 33cm baking dish. With wet hands, press half the shell mixture evenly over the base. Spread over the filling, then cover with the rest of the shell, patting it out in pieces and smoothing the joins with wet fingers."},{"text":"Score the top into diamonds, cutting right through to the base. Drizzle the olive oil over and into the cuts."},{"text":"Bake for 40 to 45 minutes until deep brown at the edges and cooked through (75°C in the centre). Rest for 10 minutes, then serve with the yoghurt mixed with cucumber."}],"notes":["Fine bulgur is essential for the shell. Coarse bulgur won't bind.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"source":"user","provenance":"ai-draft"}},{"slug":"kefta-tagine","title":"Kefta Tagine with Eggs","cuisine":"north-african","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":65,"recipe":{"id":"kefta-tagine","title":"Kefta Tagine with Eggs","summary":"Moroccan spiced beef meatballs simmered in a cumin and tomato sauce, finished with eggs baked in the pan.","cuisine":"north-african","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":25,"cookMinutes":40,"servings":4,"onePot":true,"ingredientGroups":[{"title":"Kefta","items":[{"item":"beef mince","raw":"600g beef mince","quantity":600,"unit":"g","ingredientId":"beef-mince"},{"item":"small brown onion","raw":"1 small brown onion, grated","quantity":1,"ingredientId":"brown-onion","prep":"grated"},{"item":"flat-leaf parsley","raw":"3 tbsp flat-leaf parsley, finely chopped","quantity":3,"unit":"tbsp","ingredientId":"parsley","prep":"finely chopped"},{"item":"coriander","raw":"3 tbsp coriander, finely chopped","quantity":3,"unit":"tbsp","ingredientId":"coriander","prep":"finely chopped"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"sweet paprika","raw":"1 tsp sweet paprika","quantity":1,"unit":"tsp","ingredientId":"paprika"},{"item":"ground cinnamon","raw":"1/2 tsp ground cinnamon","quantity":0.5,"unit":"tsp","ingredientId":"ground-cinnamon"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"Sauce","items":[{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onion","raw":"1 brown onion, finely chopped","quantity":1,"ingredientId":"brown-onion","prep":"finely chopped"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"sweet paprika","raw":"1 tsp sweet paprika","quantity":1,"unit":"tsp","ingredientId":"paprika"},{"item":"chilli flakes","raw":"1/2 tsp chilli flakes","quantity":0.5,"unit":"tsp","ingredientId":"chilli-flakes"},{"item":"400g tins crushed tomatoes","raw":"2 x 400g tins crushed tomatoes","quantity":2,"ingredientId":"tinned-tomatoes"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"coriander","raw":"2 tbsp coriander, chopped","quantity":2,"unit":"tbsp","ingredientId":"coriander","prep":"chopped"}]},{"title":"To serve","items":[{"item":"Crusty bread","raw":"Crusty bread, to serve","ingredientId":"crusty-bread","prep":"to serve"}]}],"steps":[{"text":"Mix all the kefta ingredients with your hands until well combined. Roll into small balls, about 2.5cm across (you'll get about 30)."},{"text":"For the sauce, heat the oil in a large, deep frying pan with a lid (or a tagine) over medium heat. Cook the onion for 6 minutes until soft, then add the garlic and spices for 1 minute."},{"text":"Add the tomatoes, water and salt and simmer for 10 minutes until slightly thickened."},{"text":"Drop the meatballs into the sauce in a single layer. Cover and simmer gently for 15 minutes, turning them once, until cooked through (75°C in the centre)."},{"text":"Make 4 hollows in the sauce and crack an egg into each. Cover and cook for 5 to 7 minutes, until the whites are set and the yolks are as you like them."},{"text":"Scatter with coriander and serve from the pan, with bread for scooping."}],"notes":["Runny yolks aren't recommended for pregnant people, young children, older people or anyone with a weakened immune system. Cook covered until the yolks are firm.","Lamb mince, or half lamb and half beef, works just as well.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"moroccan-carrot-salad","title":"Moroccan Carrot Salad","cuisine":"north-african","meal_types":["lunch","dinner"],"diets":["vegetarian","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"moroccan-carrot-salad","title":"Moroccan Carrot Salad","summary":"Just-tender carrots dressed while warm with cumin, paprika, garlic and lemon, then heaped with fresh herbs.","cuisine":"north-african","diets":["vegetarian","no-gluten","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":10,"servings":4,"onePot":false,"ingredientGroups":[{"items":[{"item":"carrots","raw":"600g carrots, peeled and cut into 5mm rounds","quantity":600,"unit":"g","ingredientId":"carrot","prep":"peeled and cut into 5mm rounds"},{"item":"extra virgin olive oil","raw":"3 tbsp extra virgin olive oil","quantity":3,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"lemon","raw":"Juice of 1 lemon","quantity":1,"ingredientId":"lemon","prep":"juiced"},{"item":"garlic","raw":"1 garlic clove, crushed","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"sweet paprika","raw":"1 tsp sweet paprika","quantity":1,"unit":"tsp","ingredientId":"paprika"},{"item":"ground cinnamon","raw":"1/4 tsp ground cinnamon","quantity":0.25,"unit":"tsp","ingredientId":"ground-cinnamon"},{"item":"honey","raw":"1 tsp honey","quantity":1,"unit":"tsp","ingredientId":"honey"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"coriander leaves","raw":"Handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"},{"item":"flat-leaf parsley leaves","raw":"Handful of flat-leaf parsley leaves, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"}]}],"steps":[{"text":"Bring a saucepan of salted water to the boil. Add the carrots and cook for 5 to 6 minutes, until just tender but still with a little bite. Drain well."},{"text":"While the carrots cook, whisk the olive oil, lemon juice, garlic, cumin, paprika, cinnamon, honey and salt in a large bowl."},{"text":"Tip the hot carrots into the dressing and toss. Leave for at least 10 minutes so they soak it up as they cool."},{"text":"Stir through the herbs just before serving, warm or at room temperature."}],"notes":["It keeps for 2 days in the fridge and tastes better on the second. Add the herbs on the day you eat it.","Good alongside grilled lamb, chicken or a pile of flatbreads and hummus."],"source":"user","provenance":"ai-draft"}},{"slug":"harcha","title":"Harcha","cuisine":"north-african","meal_types":["breakfast","snack"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"harcha","title":"Harcha","summary":"Moroccan semolina griddle breads, crumbly and buttery, split warm and spread with butter and honey.","cuisine":"north-african","diets":["vegetarian"],"mealTypes":["breakfast","snack"],"difficulty":"easy","prepMinutes":25,"cookMinutes":25,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Harcha","items":[{"item":"fine semolina","raw":"300g fine semolina","quantity":300,"unit":"g","ingredientId":"semolina"},{"item":"white sugar","raw":"1 tbsp white sugar","quantity":1,"unit":"tbsp","ingredientId":"sugar"},{"item":"baking powder","raw":"2 tsp baking powder","quantity":2,"unit":"tsp","ingredientId":"baking-powder"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"butter","raw":"100g butter, melted","quantity":100,"unit":"g","ingredientId":"butter","prep":"melted"},{"item":"milk","raw":"160ml milk, warmed","quantity":160,"unit":"ml","ingredientId":"milk","prep":"warmed"},{"item":"coarse semolina","raw":"2 tbsp coarse semolina, for dusting","quantity":2,"unit":"tbsp","ingredientId":"semolina","prep":"for dusting"}]},{"title":"To serve","items":[{"item":"butter","raw":"40g butter, softened","quantity":40,"unit":"g","ingredientId":"butter","prep":"softened"},{"item":"honey","raw":"3 tbsp honey","quantity":3,"unit":"tbsp","ingredientId":"honey"}]}],"steps":[{"text":"Mix the fine semolina, sugar, baking powder and salt in a bowl. Pour in the melted butter and rub it through with your fingers until the mixture looks like damp sand."},{"text":"Add the warm milk and bring it together into a soft, slightly sticky dough. Don't knead it. Cover and rest for 10 minutes so the semolina can soak up the liquid."},{"text":"Divide into 8 balls. Flatten each between your palms into a round about 1cm thick and press both sides into the coarse semolina."},{"text":"Heat a heavy frying pan over medium-low heat with no oil. Cook the harcha in batches for 5 to 6 minutes a side, until golden and cooked through. Keep the heat gentle; they burn before the middle cooks if it's too high."},{"text":"Serve warm, split open and spread with butter and honey."}],"notes":["They're best within a few hours. Leftovers warm up well in a dry pan.","For a savoury version, leave out the sugar and serve with soft cheese."],"source":"user","provenance":"ai-draft"}},{"slug":"chicken-yassa","title":"Chicken Yassa","cuisine":"west-african","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"medium","total_minutes":200,"recipe":{"id":"chicken-yassa","title":"Chicken Yassa","summary":"Senegalese chicken marinated in lemon and mustard, braised in a pot of sweet, slow-cooked onions.","cuisine":"west-african","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":140,"cookMinutes":60,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Chicken and marinade","items":[{"item":"bone-in chicken thighs","raw":"1.2kg bone-in chicken thighs, skin on","quantity":1.2,"unit":"kg","ingredientId":"chicken-thigh-bone-in","prep":"skin on"},{"item":"brown onions","raw":"4 brown onions, thinly sliced","quantity":4,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"lemons","raw":"Juice of 3 lemons","quantity":3,"ingredientId":"lemon","prep":"juiced"},{"item":"Dijon mustard","raw":"2 tbsp Dijon mustard","quantity":2,"unit":"tbsp","ingredientId":"dijon-mustard"},{"item":"garlic","raw":"4 garlic cloves, crushed","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"To cook","items":[{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"chicken stock","raw":"250ml chicken stock","quantity":250,"unit":"ml","ingredientId":"chicken-stock"},{"item":"bay","raw":"1 bay leaf","quantity":1,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"scotch bonnet chilli","raw":"1 scotch bonnet chilli, pierced with a knife (or 1 long red chilli)","quantity":1,"ingredientId":"scotch-bonnet","prep":"pierced with a knife","note":"or 1 long red chilli"},{"item":"green olives","raw":"80g green olives, pitted (optional)","quantity":80,"unit":"g","ingredientId":"green-olive","prep":"pitted","optional":true}]},{"title":"To serve","items":[{"item":"white rice","raw":"300g white rice","quantity":300,"unit":"g","ingredientId":"white-rice"}]}],"steps":[{"text":"Whisk the lemon juice, mustard, garlic, salt and pepper in a large bowl. Add the chicken and onions and toss well. Cover and refrigerate for at least 2 hours, or overnight."},{"text":"Lift the chicken out of the marinade and pat the skin dry. Drain the onions in a sieve over a bowl, keeping the liquid."},{"text":"Heat the oil in a large heavy pot over medium-high heat. Brown the chicken skin-side down for 6 to 8 minutes until golden, turn for 2 minutes, then set aside."},{"text":"Lower the heat to medium and add the onions. Cook for 20 minutes, stirring often, until soft, sweet and lightly golden."},{"text":"Pour in the saved marinade and the stock, and add the bay leaf and whole chilli. Bring to the boil. Nestle the chicken in skin-side up, cover and simmer gently for 30 to 35 minutes, until the chicken is cooked through (75°C at the bone). Stir in the olives for the last 5 minutes."},{"text":"Meanwhile, cook the rice until tender and fluffy. Take out the chilli and bay leaf and serve the chicken, which should be tender and falling from the bone, and the soft, glossy onions over the rice."}],"notes":["The raw-chicken marinade is safe here because it's boiled in the pot before the chicken goes back in.","Scotch bonnets are fierce. Left whole and pierced they give fragrance and moderate heat; chop one in if you like it hot.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"puff-puff","title":"Puff-Puff","cuisine":"west-african","meal_types":["snack"],"diets":["vegetarian","vegan","no-dairy"],"difficulty":"medium","total_minutes":100,"recipe":{"id":"puff-puff","title":"Puff-Puff","summary":"Soft, golden West African doughnut balls, lightly sweet with a hint of nutmeg.","cuisine":"west-african","diets":["vegetarian","vegan","no-dairy"],"mealTypes":["snack"],"difficulty":"medium","prepMinutes":75,"cookMinutes":25,"servings":6,"onePot":false,"ingredientGroups":[{"items":[{"item":"plain flour","raw":"500g plain flour","quantity":500,"unit":"g","ingredientId":"plain-flour"},{"item":"instant dried yeast","raw":"2 tsp instant dried yeast","quantity":2,"unit":"tsp","ingredientId":"yeast"},{"item":"caster sugar","raw":"100g caster sugar","quantity":100,"unit":"g","ingredientId":"caster-sugar"},{"item":"ground nutmeg","raw":"1/2 tsp ground nutmeg","quantity":0.5,"unit":"tsp","ingredientId":"nutmeg"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"warm water","raw":"420ml warm water","quantity":420,"unit":"ml","ingredientId":"water"},{"item":"Neutral oil","raw":"Neutral oil, for deep-frying","ingredientId":"neutral-oil","prep":"for deep-frying"},{"item":"icing sugar","raw":"2 tbsp icing sugar, for dusting (optional)","quantity":2,"unit":"tbsp","ingredientId":"icing-sugar","prep":"for dusting","optional":true}]}],"steps":[{"text":"Whisk the flour, yeast, sugar, nutmeg and salt in a large bowl. Add the warm water and beat with a wooden spoon or your hand for 2 to 3 minutes into a thick, smooth, sticky batter."},{"text":"Cover and leave somewhere warm for about 1 hour, until doubled and full of bubbles."},{"text":"Heat 5cm of oil in a heavy saucepan to 170°C. Use a thermometer if you have one; a small blob of batter should sizzle and rise straight away."},{"text":"Scoop up a walnut-sized piece of batter with a wet tablespoon and push it into the oil with another wet spoon. Fry 6 to 8 at a time for 3 to 4 minutes, turning, until deep golden all over. Break the first one open to check the middle is cooked."},{"text":"Drain on paper towel and dust with icing sugar if you like. Best eaten warm."}],"notes":["Never leave hot oil unattended, keep the pan on a back burner, and let the oil cool completely before moving it.","If they brown before the middle cooks, the oil is too hot. Let it drop back to 170°C."],"source":"user","provenance":"ai-draft"}},{"slug":"tomato-bredie","title":"Tomato Bredie","cuisine":"south-african","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":175,"recipe":{"id":"tomato-bredie","title":"Tomato Bredie","summary":"A slow South African lamb and tomato stew, warmly spiced with cinnamon and ginger, with potatoes cooked in.","cuisine":"south-african","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":25,"cookMinutes":150,"servings":5,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Stew","items":[{"item":"bone-in lamb shoulder chops","raw":"1.2kg bone-in lamb shoulder chops, cut into large pieces","quantity":1.2,"unit":"kg","ingredientId":"lamb-shoulder","prep":"cut into large pieces"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onions","raw":"2 brown onions, sliced","quantity":2,"ingredientId":"brown-onion","prep":"sliced"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"grated ginger","raw":"1 tbsp grated ginger","quantity":1,"unit":"tbsp","ingredientId":"ginger"},{"item":"cinnamon","raw":"1 cinnamon stick","quantity":1,"unit":"stick","ingredientId":"cinnamon-stick"},{"item":"ground cloves","raw":"1/4 tsp ground cloves","quantity":0.25,"unit":"tsp","ingredientId":"ground-cloves"},{"item":"chilli flakes","raw":"1/2 tsp chilli flakes","quantity":0.5,"unit":"tsp","ingredientId":"chilli-flakes"},{"item":"ripe tomatoes","raw":"800g ripe tomatoes, chopped","quantity":800,"unit":"g","ingredientId":"tomato","prep":"chopped"},{"item":"tomato paste","raw":"2 tbsp tomato paste","quantity":2,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"brown sugar","raw":"1 tbsp brown sugar","quantity":1,"unit":"tbsp","ingredientId":"brown-sugar"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"},{"item":"waxy potatoes","raw":"600g waxy potatoes, peeled and halved","quantity":600,"unit":"g","ingredientId":"waxy-potato","prep":"peeled and halved"}]},{"title":"To serve","items":[{"item":"white rice","raw":"300g white rice","quantity":300,"unit":"g","ingredientId":"white-rice"}]}],"steps":[{"text":"Season the lamb with the salt and pepper. Heat the oil in a large heavy pot over medium-high heat and brown the lamb in batches, 5 minutes a batch. Set aside."},{"text":"Lower the heat to medium. Add the onions and cook for 10 minutes until soft and golden. Add the garlic, ginger, cinnamon, cloves and chilli flakes and cook for 1 minute."},{"text":"Add the tomatoes, tomato paste, sugar and water, scraping up the browned bits. Return the lamb and its juices. Bring to a simmer, cover and cook on low heat for 1 1/2 hours, stirring now and then."},{"text":"Add the potatoes, pushing them under the sauce. Cover and simmer for 40 minutes more, until the lamb is falling off the bone and the potatoes are tender. If the sauce is thin, simmer uncovered for the last 10 minutes."},{"text":"Meanwhile, cook the rice until tender and fluffy. Take out the cinnamon stick, taste for salt and serve the bredie, once the meat is tender and the sauce thick, over the rice."}],"notes":["Like most stews it's better the next day. Cool it quickly, refrigerate within an hour and reheat until bubbling.","Use ripe summer tomatoes if you can. In winter, swap half for a 400g tin of chopped tomatoes.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"source":"user","provenance":"ai-draft"}},{"slug":"chakalaka-pap","title":"Chakalaka and Pap","cuisine":"south-african","meal_types":["dinner"],"diets":["vegetarian","vegan","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"chakalaka-pap","title":"Chakalaka and Pap","summary":"South Africa's spicy vegetable and bean relish, served on soft, steaming maize porridge.","cuisine":"south-african","diets":["vegetarian","vegan","no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":35,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Chakalaka","items":[{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, diced","quantity":1,"ingredientId":"brown-onion","prep":"diced"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"grated ginger","raw":"1 tbsp grated ginger","quantity":1,"unit":"tbsp","ingredientId":"ginger"},{"item":"long red chilli","raw":"1 long red chilli, finely chopped","quantity":1,"ingredientId":"red-chilli","prep":"finely chopped"},{"item":"curry powder","raw":"2 tsp curry powder","quantity":2,"unit":"tsp","ingredientId":"curry-powder"},{"item":"red capsicum","raw":"1 red capsicum, diced","quantity":1,"ingredientId":"capsicum","prep":"diced"},{"item":"green capsicum","raw":"1 green capsicum, diced","quantity":1,"ingredientId":"green-capsicum","prep":"diced"},{"item":"carrots","raw":"3 carrots, coarsely grated","quantity":3,"ingredientId":"carrot","prep":"coarsely grated"},{"item":"tomatoes","raw":"2 tomatoes, chopped","quantity":2,"ingredientId":"tomato","prep":"chopped"},{"item":"baked beans","raw":"420g tin baked beans","quantity":420,"unit":"g","ingredientId":"baked-beans","note":"tin"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"Pap","items":[{"item":"water","raw":"1.25L water","quantity":1.25,"unit":"l","ingredientId":"water"},{"item":"polenta","raw":"250g polenta (or white maize meal)","quantity":250,"unit":"g","ingredientId":"polenta","note":"or white maize meal"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"butter","raw":"20g butter (optional)","quantity":20,"unit":"g","ingredientId":"butter","optional":true}]}],"steps":[{"text":"For the chakalaka, heat the oil in a large frying pan over medium heat. Cook the onion for 5 minutes, then add the garlic, ginger, chilli and curry powder and cook for 1 minute."},{"text":"Add both capsicums and the carrots and cook for 8 minutes, stirring, until softened. Add the tomatoes and cook for 5 minutes until they break down."},{"text":"Stir in the baked beans and salt and simmer for 5 minutes until thick. Taste for salt and heat."},{"text":"Meanwhile, make the pap. Bring the water and salt to the boil in a heavy saucepan. Whisking all the time, pour in the polenta in a slow, steady stream. Turn the heat to low and cook for 25 to 30 minutes, stirring often with a wooden spoon, until thick and smooth. Stir in the butter if using. It spits as it cooks, so keep a lid half on."},{"text":"Spoon the pap into bowls and top with the chakalaka. It's good hot, warm or at room temperature."}],"notes":["Instant polenta cooks in about 5 minutes; follow the packet. White maize meal from an African grocer gives the most authentic pap.","Chakalaka is also the classic side at a braai, next to sausages and chops."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;